        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos I.42</em> <small>(c. 350 AD)</small><p>&#x27;Far above all principality, and power, and might, and dominion, and every name that is named, not only in this world, but also in that which is to come&#x27; — Athanasius marks hyperanō pasēs archēs (far-above every principality) as the exaltation-supremacy Pauline-anchor paired with Phil 2:9 (highly-exalted). The Christ-incarnate-and-risen is RANKED-ABOVE every conceivable angelic or human authority — in BOTH this-age AND the-age-to-come (eschatological-permanence). Tewahedo angelology preserves this Pauline-supremacy-of-Christ at the Christ-Pantocrator iconography of every Tewahedo-dome.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
