        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>De Incarnatione Verbi §16</em> <small>(c. 350 AD)</small><p>&#x27;For he is our peace, who hath made both one, and hath broken down the middle wall of partition between us&#x27; — Athanasius marks autos gar estin hē eirēnē hēmōn (he himself is our peace) as the Pauline-incarnational-peace-anchor. Christ does not merely-make-peace; he IS peace (predicate-identity, like 1 Cor 1:30). The both-made-one names Jew-Gentile-reconciliation but the deeper-anchor is human-divine-reconciliation: the Word&#x27;s-incarnate-Person IS the union-of-the-two-natures, making him constitutively-peace between God and humanity. Tewahedo Aksumite-Gentile-mission theology cites Eph 2:14-18 at the Frumentius-mission anchor.</p></aside>',
        "Athanasius of Alexandria, De Incarnatione Verbi (On the Incarnation), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 25 (1857).",
